    {
        get
        {
            var data = new TheoryData<string>();
            foreach (var name in Cases.Keys)
            {
                data.Add(name);
            }
            return data;
        }
    }

    public static TheoryData<string> PagedOperations
    {
        get
        {
            var data = new TheoryData<string>();
            foreach (var pair in Cases)
            {
                if (pair.Value.Cardinality == "page")
                {
                    data.Add(pair.Key);
                }
            }
            return data;
        }
    }

    public static TheoryData<string> ModelNames
    {
        get
        {
            var data = new TheoryData<string>();
            foreach (var name in Fixtures.Models().EnumerateObject())
            {
                data.Add(name.Name);
            }
            return data;
        }
    }

    private static T Parse<T>(string json) => JsonSerializer.Deserialize<T>(json)!;

    /// <summary>The query string as a multimap, so one key may carry several values.</summary>
    private static Dictionary<string, List<string>> ParseQuery(string raw)
    {
        var parsed = new Dictionary<string, List<string>>();
        foreach (var pair in raw.TrimStart('?').Split('&', StringSplitOptions.RemoveEmptyEntries))
        {
            var split = pair.IndexOf('=', StringComparison.Ordinal);
            var name = Uri.UnescapeDataString(split < 0 ? pair : pair[..split]);
            var value = split < 0 ? string.Empty : Uri.UnescapeDataString(pair[(split + 1)..]);
            if (!parsed.TryGetValue(name, out var values))
            {
                values = [];
                parsed[name] = values;
            }
            values.Add(value);
        }
        return parsed;
    }

    private static ZelfClient ClientFor(Stub stub) =>
        new(new ZelfClientOptions
        {
            ApiKey = Key,
            BaseUrl = "https://api.hellozelf.com",
            MaxRetries = 0,
            HttpClient = new HttpClient(stub),
        });

    [Theory]
    [MemberData(nameof(Operations))]
    public async Task RequestMapping(string operation)
    {
        var entry = Cases[operation];
        var payload = Fixtures.EnvelopeFor(operation);
        var stub = new Stub((n, request) => (HttpStatusCode.OK, payload, null));
        using var client = ClientFor(stub);

        await entry.Call(client, entry.ParamsJson);

        Assert.Single(stub.Requests);
        var sent = stub.Requests[0];
        Assert.Equal(entry.Method, sent.Method.Method);
        Assert.Equal(entry.Path, sent.RequestUri!.AbsolutePath);
        var query = ParseQuery(sent.RequestUri!.Query);
        foreach (var expected in entry.Query)
        {
            Assert.Equal(
                expected.Value,
                query.TryGetValue(expected.Key, out var values) ? values : []);
        }
        if (entry.Body.Length > 0)
        {
            using var body = JsonDocument.Parse(stub.Bodies[0]);
            foreach (var key in entry.Body)
            {
                Assert.True(body.RootElement.TryGetProperty(key, out _), operation + " dropped " + key);
            }
        }
    }

    /// <summary>A caller's own key header must not replace or duplicate the client's.</summary>
    [Fact]
    public async Task ApiKeyHeaderIsSentOnce()
    {
        var entry = Cases.First();
        var payload = Fixtures.EnvelopeFor(entry.Key);
        var stub = new Stub((n, request) => (HttpStatusCode.OK, payload, null));
        using var client = new ZelfClient(new ZelfClientOptions
        {
            ApiKey = Key,
            BaseUrl = "https://api.hellozelf.com",
            MaxRetries = 0,
            HttpClient = new HttpClient(stub),
            DefaultHeaders = { { "X-API-Key", "sk_zelf_" + new string('9', 64) } },
        });

        await entry.Value.Call(client, entry.Value.ParamsJson);

        Assert.Equal(new[] { Key }, stub.Requests[0].Headers.GetValues("x-api-key"));
    }

