    [Theory]
    [MemberData(nameof(PagedOperations))]
    public async Task AutoPagingWalks(string operation)
    {
        var entry = Cases[operation];
        var first = Fixtures.EnvelopeFor(operation).Replace("\"next\": null", "\"next\": 2");
        var second = Fixtures.EnvelopeFor(operation);
        var stub = new Stub((n, request) =>
            (HttpStatusCode.OK, n == 1 ? first : second, null));
        using var client = ClientFor(stub);

        var page = await entry.Call(client, entry.ParamsJson);
        var walked = await entry.Walk!(page!);

        Assert.Equal(2, stub.Requests.Count);
        Assert.True(walked > 0);
    }

