    /// <summary>Reading All runs the class initialiser.</summary>
    [Theory]
    [MemberData(nameof(EnumClasses))]
    public void EnumConstantsAreListed(string name)
    {
        var type = typeof(ZelfClient).Assembly.GetType("Zelf." + name);
        if (type is null)
        {
            return;
        }
        var all = type.GetField("All")?.GetValue(null);
        Assert.NotNull(all);
    }

    [Theory]
    [MemberData(nameof(ModelNames))]
    public void ModelsRoundTrip(string name)
    {
        var type = typeof(ZelfClient).Assembly.GetType("Zelf." + name);
        if (type is null)
        {
            return;
        }
        var sample = Fixtures.Models().GetProperty(name).GetRawText();
        var parsed = JsonSerializer.Deserialize(sample, type);
        Assert.NotNull(parsed);
        Assert.NotNull(parsed!.ToString());
        parsed.GetHashCode();

        // A record with a List member compares collections by reference, so two
        // deserializations never match. The serialized form is the real check.
        var again = JsonSerializer.Deserialize(JsonSerializer.Serialize(parsed, type), type);
        Assert.Equal(JsonSerializer.Serialize(parsed, type), JsonSerializer.Serialize(again, type));
        Assert.Equal(parsed, parsed);
        Assert.False(parsed.Equals(null));
        foreach (var property in type.GetProperties())
        {
            property.GetValue(parsed);
        }
    }
